-- 描述中文译文，由 docs/local/description-translation.CSV 回填
-- 共 134 条 UPDATE；按 name_en 匹配，匹配不到的行不会有任何效果。
-- 回填后清一次图鉴缓存，接口才会拿到新译文（采集完成后也会自动清）。

UPDATE item SET description_zh = '飞机餐是 PEAK 中的一种包装食品，可在普通行李箱或大号行李箱中找到。' WHERE name_en = 'Airline Food';
UPDATE item SET description_zh = '芦荟是 PEAK 中的一种消耗品，生长在方山。使用芦荟可移除 50 点热量。' WHERE name_en = 'Aloe Vera';
UPDATE item SET description_zh = '古老玩偶是 PEAK 中的一种神秘道具，完成挑战室后可在方山的古墓中找到。虽然古老玩偶不会出现在古老行李箱中，也无法从古代雕像处获得，它仍被视作神秘道具，拾取时会解锁「玄学奖章」。手持古老玩偶可让玩家获得无敌。把古老玩偶扔进熔炉的岩浆或城塞的岩浆坩埚中会摧毁它，并解锁「24K 奖章」。古老玩偶无法烹饪。仅能在古墓中找到。手持期间可获得无敌，免疫一切伤害与负面状态效果（击退除外），并阻止消耗。扔进熔炉的岩浆中可获得「24K 奖章」。烹饪：无法烹饪。' WHERE name_en = 'Ancient Idol';
UPDATE item SET description_zh = '反重绳索炮是 PEAK 中的一种可放置的神秘道具。使用反重绳索炮会把一段 7.25 米长的反重绳索（见反重绳索）附着到最远 48 米外的表面上，通过钩子把绳索一端嵌入该表面。它是绳索炮的反重版本。反重绳索炮属于神秘道具，因此只能在古代雕像中找到，或从古老行李箱中开出。烹饪反重绳索炮会立即将其烧焦，使其无法使用。射出鱼叉，接触可附着的表面后会展开一段反重绳索。掉落的反重绳索炮会飘走！烹饪：立即烧焦。' WHERE name_en = 'Anti-Rope Cannon';
UPDATE item SET description_zh = '反重绳索是 PEAK 中的一种可放置的神秘道具。它提供总长 12.5 米的可攀爬反重力绳索，可按 0.75 米至 10 米的长度自行放置。绳索会向上飘浮，让童子军能够抵达难以到达的地方。作为神秘道具，反重绳索只能在古代雕像中找到，或从古老行李箱中开出。反重绳索具有负重量，会减少童子军携带的总重量（注意天阶 3 的重量修正仍作用于反重绳索）。丢下反重绳索会让它飘走。烹饪反重绳索会立即将其烧焦，使其无法使用（但它仍保留负重量）。可生成一段可攀爬的反重绳索（最长 10 米），能附着在任何可攀爬表面上。反重绳索会无视重力向上飘浮。每卷包含 12.5 米反重绳索。掉落的反重绳索会向上飘浮！烹饪：立即烧焦。' WHERE name_en = 'Anti-Rope Spool';
UPDATE item SET description_zh = '反重炮是 PEAK 中的一种可放置的神秘道具。使用反重炮会向最远 40 米处的空中或表面射出一个反重球，直径 16 米。反重球内的一切都会受到反向重力。反重炮最多可使用 3 次，之后便无法使用。反重球在环境中持续一分钟，但不计入已放置物品，因此在尝试解锁「环保奖章」时可以安全使用。烹饪反重炮时它会爆炸，生成一个直径约为 32 米的更大反重球。烹饪：爆炸，生成直径翻倍的反重球。' WHERE name_en = 'Anti-Zooka';
UPDATE item SET description_zh = '解毒剂是 PEAK 中的一种消耗品。一支解毒剂最多可使用 3 次，每次使用可移除 35 点中毒、35 点孢子、10 点热量以及中毒持续效果。烹饪或投掷解毒剂会使其碎裂，最多移除 4.8 米内玩家身上的 20 点中毒，具体数值取决于距离。它不会移除尚未结束的中毒持续效果。不过，直接朝玩家投掷解毒剂会砸中他们，使其进入布娃娃状态。由于中毒主要出现在雨林，而孢子只出现在森蕈，解毒剂只会在这些生态的行李箱中生成。烹饪：爆炸，最多移除 4.8 米内所有玩家的 20 点中毒。' WHERE name_en = 'Antidote';
UPDATE item SET description_zh = '背包是一种装备道具，可扩展童子军可用的物品存储空间，提供四个新的物品栏位，让玩家在攀爬过程中能携带更多物品。背包始终占据第四个物品栏，该栏位专用于可附着在童子军身上的装备。坠机点可找到一个背包，除熔炉与城塞外，每处营火旁还能额外找到一个背包。烹饪背包不会影响其功能，但会烤熟其中的所有物品。可在坠机点与营火处找到。可额外携带 4 件物品。' WHERE name_en = 'Backpack';
UPDATE item SET description_zh = '气球是 PEAK 中的一种消耗品，可在行李箱中找到。使用它会把一只气球附着到玩家身上。丢下气球会让它飞走。虽然物品栏图标显示为红色，但气球模型本身有六种颜色：红、橙、黄、绿、蓝、紫。烹饪气球会使其爆裂，摧毁该物品。任意时刻身上附着 6 只或更多气球会解锁「航天奖章」。气球束是另一件独立物品，一次提供 3 只气球，可一次性全部附着，也可放在同一个物品栏中携带。每只气球降低 18% 重力，持续 2 分钟或直到移动 100 米。同时使用 6 只气球可实现有限飞行。可与自身及气球束叠加。手持、放在物品栏或背包中时会被动移除状态。掉落的气球会飘走！烹饪：爆裂。' WHERE name_en = 'Balloon';
UPDATE item SET description_zh = '一束气球是 PEAK 中的一种消耗品，可在行李箱中找到。使用它会把 3 只气球附着到玩家身上。丢下气球束会让它飞走。烹饪气球束会使其中的气球爆裂，摧毁该物品。每束气球降低 54% 重力，持续 2 分钟或直到移动 100 米。同时使用 2 束气球可实现有限飞行。可与自身及气球叠加。手持、放在物品栏或背包中时会被动移除状态。掉落的气球会飘走！烹饪：爆裂。' WHERE name_en = 'Balloon Bunch';
UPDATE item SET description_zh = '绷带是 PEAK 中的一种消耗品，可在行李箱中找到。使用绷带可移除 30 点伤害。烹饪绷带没有任何效果，即使被烧焦也一样。使用时间为 4 秒。烹饪：无效果。' WHERE name_en = 'Bandages';
UPDATE item SET description_zh = '篮球是 PEAK 中的一种物品，可在机场找到。机场内共有四个篮球，篮球场两侧的每个球筐中各生成两个。朝另一名童子军投掷篮球会砸中他们，使其进入布娃娃状态。尽管机场内无法烹饪，烹饪篮球仍会使其爆裂，摧毁该物品。烹饪：爆裂。' WHERE name_en = 'Basketball';
UPDATE item SET description_zh = '蜂巢是 PEAK 中的一种物品，可在雨林的树上找到。打破蜂巢可获得四个蜂巢蜜。烹饪蜂巢会把其烹饪等级传递给其中的蜂巢蜜。' WHERE name_en = 'Beehive';
UPDATE item SET description_zh = '好大蛋是 PEAK 中的一种物品，可在火山岩石上的巢穴中找到，包括秃鹫巡视的那些巢穴。投掷好大蛋可将其打碎，得到煎蛋，或有 10% 几率得到「鸟」烧熟了。烹饪煎蛋是解锁「美食家奖章」的必要条件，因为「鸟」烧熟了不计入其中。烹饪好大蛋会把其烹饪等级传递给里面的物品（可能未烹饪的鸟除外）。' WHERE name_en = 'Big Egg';
UPDATE item SET description_zh = '大棒棒糖是 PEAK 中的一种包装食品，可在普通行李箱、大号行李箱与探险家行李箱中找到。机场自拍亭中还能找到一个较小的、无法使用的版本。食用大棒棒糖会让你获得 11 秒的无限体力，攀爬时持续时间会缩短至 8 秒。这意味着你可以先等 3 秒再开始攀爬，仍能获得完整的 8 秒无限体力攀爬。效果结束后，玩家会在 10 秒内累积 32.5 点困倦。烹饪大棒棒糖可移除此惩罚。可短时间提供无限体力。烹饪：移除困倦效果。' WHERE name_en = 'Big Lollipop';
UPDATE item SET description_zh = '宾邦是 PEAK 中的一种物品，是 BingBong 航空吉祥物的毛绒玩偶。它总会出现在海岸的坠机点，以及机场的自拍亭中。按住鼠标左键取出宾邦时会挤压它，随机播放一句语音，用来回应玩家提出的问题，分别表示肯定、否定、不确定或无关。所有回应（而非回应类型）出现的概率相同。烹饪宾邦会让它的语音音调与音量每次都下降。烹饪宾邦 4 次会将其烧焦，使它停止说话。把烧焦过一次的宾邦收起来再拿出会使其重新开口，但第 5 次烹饪会永久让它沉默。带着宾邦（放在童子军的物品栏或背包中）逃离岛屿会为队伍中所有玩家解锁「宾邦奖章」。如果在自定义探险中把所有能在行李箱中生成或从古代雕像获得的物品移出生成池，会额外生成宾邦来顶替它们。可以问它「是」或「否」的问题。可用于解锁奖章。烹饪：降低语音的音调与音量。' WHERE name_en = 'Bing Bong';
UPDATE item SET description_zh = '望远镜是 PEAK 中的一种装备道具，可在海岸的坠机点找到。使用望远镜可以拉近视野，更容易看清远处。机场自拍亭中还能找到一个没有放大效果的版本。在方山白天的阳光下用望远镜直视太阳，可获得「天文学奖章」。用于看得更远。可用于解锁奖章。' WHERE name_en = 'Binoculars';
UPDATE item SET description_zh = '主教是 PEAK 中的一种物品，可在机场找到。被丢下时，棋子会自动锁入地面，以免被意外碰移。机场内共有四枚主教棋子，棋盘上黑白双方各摆两枚。' WHERE name_en = 'Bishop';
UPDATE item SET description_zh = '黑葚莓是 PEAK 中的一种天然食物，生长在雨林的巨型常春藤上。' WHERE name_en = 'Black Clusterberry';
UPDATE item SET description_zh = '吹箭筒是 PEAK 中的一种消耗品，在多人游戏中可在普通行李箱与大号行李箱中找到。可以用它朝另一名童子军射出飞镖，清除目标身上的大部分状态效果。被射中的童子军会因为受到 120 点困倦而睡着。这会妨碍解锁「生存专家奖章」，因为该童子军必定会失去意识。（烹饪吹箭筒会使其造成 150 点而非 120 点困倦，使用者自身还会获得 10 点困倦。）目前存在 bug，即使经过烹饪也仍为 120 点，并附带 10 点。射出一支飞镖，对目标童子军造成以下效果：清除大部分状态效果，并造成 120 点困倦。单人游戏中不会生成。烹饪：将 120 改为 150。' WHERE name_en = 'Blowgun';
UPDATE item SET description_zh = '蓝莓蕉是 PEAK 中的一种天然食物，生长在雨林的藤蔓上。食用蓝莓蕉会恢复 30 点饱食度。吃完蓝莓蕉后，玩家会获得一张蓝莓蕉皮。如果把蓝莓蕉喂给其他玩家，对方会获得蕉皮；若对方的物品栏与双手都已满，蕉皮会掉在他们脚下。食用后产出一张蓝莓蕉皮。' WHERE name_en = 'Blue Berrynana';
UPDATE item SET description_zh = '蓝莓蕉皮是 PEAK 中的一种物品，食用雨林的蓝莓蕉后获得。玩家走过蕉皮会滑倒摔在地上，短暂失去控制。来源：食用蓝莓蕉后获得。' WHERE name_en = 'Blue Berrynana Peel';
UPDATE item SET description_zh = '蓝菇莓是菇莓的一种。食用时会产生一种随机的不良效果。烹饪蓝菇莓可移除孢子效果。食用时产生一种不良效果。烹饪：移除 5 点孢子效果。' WHERE name_en = 'Blue Shroomberry';
UPDATE item SET description_zh = '弹力菇是 PEAK 中的一种物品，可在森蕈的陡峭表面上找到。投掷或丢下它，会在与地形、物品、玩家或其它具有有效碰撞体积的物体接触处生成一个弹性平台。被投出的物品与坠落的玩家也能让弹力菇变成平台。在弹力菇上弹跳会恢复一小部分体力。在弹力菇上弹起 40 米会解锁「真菌杂技奖章」。投掷后生成一个弹性平台。' WHERE name_en = 'Bounce Fungus';
UPDATE item SET description_zh = '棕莓蕉是 PEAK 中的一种天然食物，生长在雨林与雾沼的藤蔓上。食用棕莓蕉会恢复 15 点饱食度并获得 10 点加成。吃完棕莓蕉后，玩家会获得一张棕莓蕉皮。如果把棕莓蕉喂给其他玩家，对方会获得蕉皮；若对方的物品栏与双手都已满，蕉皮会掉在他们脚下。食用后产出一张棕莓蕉皮。' WHERE name_en = 'Brown Berrynana';
UPDATE item SET description_zh = '棕莓蕉皮是 PEAK 中的一种物品，食用雨林或雾沼的棕莓蕉后获得。玩家走过蕉皮会滑倒摔在地上，短暂失去控制。来源：食用棕莓蕉后获得。' WHERE name_en = 'Brown Berrynana Peel';
UPDATE item SET description_zh = '喇叭是 PEAK 中的一种装备道具，可在海岸的坠机点找到。使用喇叭会发出能传到很远处的响亮声音，最远可在 150 至 175 米外听到。音高取决于视线方向，向下直视为最低音，向上直视为最高音。机场自拍亭中还能找到一个无法使用的版本。烹饪喇叭会让其音高在约 3 秒内上下抖动，再次烹饪抖动幅度会更大。站在水豚旁边使用喇叭会解锁「对牛弹琴奖章」。使用时吹奏一个音符。可用于解锁奖章。烹饪：根据烹饪次数附加音高调制。' WHERE name_en = 'Bugle';
UPDATE item SET description_zh = '友谊喇叭是 PEAK 中的一种神秘装备道具，在多人游戏中可以找到。当一名童子军吹奏喇叭时，56 米半径内的其他所有玩家都会获得 0.5 秒的无限体力。喇叭的总使用时长为 7.5 秒。这使它成为帮助队友跨越长距离垂直落差的绝佳道具。站在水豚旁边使用友谊喇叭可获得「对牛弹琴奖章」，不过用普通喇叭来做这件事更不浪费。即使友谊喇叭已无剩余使用时长，用掉它仍会解锁奖章。使用时吹奏一个音符。吹奏期间为半径内的大范围童子军提供无限体力，总计最长 7.5 秒。可用于解锁奖章。单人游戏中不会生成。' WHERE name_en = 'Bugle of Friendship';
UPDATE item SET description_zh = '喇叭菇是 PEAK 中的一种蘑菇，可在海岸、雨林、森蕈与方山找到。它可以作为食物食用。有毒变种的菌柄更粗糙且带有棱纹，会在食用 10 秒后开始，于 8 秒内缓慢造成 20 点中毒。' WHERE name_en = 'Bugle Shroom';
UPDATE item SET description_zh = '喇叭菇（有毒）是 PEAK 中的一种蘑菇，可在海岸、雨林、森蕈与方山找到。它可以作为食物食用。有毒变种的菌柄更粗糙且带有棱纹，会在食用 10 秒后开始，于 8 秒内缓慢造成 20 点中毒。' WHERE name_en = 'Bugle Shroom (Poisonous)';
UPDATE item SET description_zh = '号角是 PEAK 中的一种限时物品，曾在 PEAK × bbno$ 演唱会活动期间开放。它可以在海岸的一座雕像上找到。使用号角约 1 秒即可获得完全士气加成，并触发 bbno$ 演唱会。使用一次后便无法再次使用。或许这样最好。号角与童军领队的喇叭共用模型，并会发出类似的失真噪音。' WHERE name_en = 'Bugle?';
UPDATE item SET description_zh = '馒头菇是 PEAK 中的一种蘑菇，可在海岸、雨林、森蕈与方山找到。它可以作为食物食用。有毒变种的菌盖上长有斑点，取代了裂开的「X」形状，会在食用 10 秒后开始，于 12 秒内缓慢造成 30 点中毒。' WHERE name_en = 'Button Shroom';
UPDATE item SET description_zh = '馒头菇（有毒）是 PEAK 中的一种蘑菇，可在海岸、雨林、森蕈与方山找到。它可以作为食物食用。有毒变种的菌盖上长有斑点，取代了裂开的「X」形状，会在食用 10 秒后开始，于 12 秒内缓慢造成 30 点中毒。' WHERE name_en = 'Button Shroom (Poisonous)';
UPDATE item SET description_zh = '仙人球是 PEAK 中的一种物品，可在方山找到。仙人球会粘在玩家身上，并持续施加 20 点荆棘，直到被投出或从玩家身上摘下。由于具有黏性，它必须被投掷出去（投掷力度 40% 或更高），无法丢下。身上粘着 5 个或更多仙人球会解锁「刺绣奖章」。手持的仙人球不计入该数量。刺莓不会长在小仙人球上。' WHERE name_en = 'Cactus';
UPDATE item SET description_zh = '烛台是 PEAK 中的物品，只会在雾沼或城塞的行李箱中出现。点燃后，烛台周围 7 米内的所有玩家不会受到困倦雾霾造成的困倦影响，4 米内的雾沼视觉效果也会随之消散。烛台可点燃 30 秒，用尽后即耗尽。烛台可用于焚烧大幽灵，为玩家解锁成就「驱魔人」。烹饪烛台没有任何效果。' WHERE name_en = 'Candlestick';
UPDATE item SET description_zh = '锁链发射器是 PEAK 中的可放置物品，可在海岸之后的普通行李箱箱与大号行李箱，以及任意位置的探险家行李箱箱中找到。站在地面上使用锁链发射器，会在当前位置与最远 80 米外的墙面之间架出一条锁链，并消耗掉发射器。视线过于朝上或朝下时无法使用锁链发射器。烹饪锁链发射器会立即将其烧焦，使其无法使用。锁链可在两点之间架出一段像藤蔓一样可供攀爬的通道。锁链从使用者发射的位置起始。锁链发射器无法向上方发射锁链。烹饪：立即烧焦。' WHERE name_en = 'Chain Launcher';
UPDATE item SET description_zh = '检查点旗标是 PEAK 中的可放置物品，可在行李箱中找到。它是一面可放置的旗帜，为放置它的玩家提供一个一次性复活点。放置后，旗帜会染上放置者所属童子军的颜色。检查点旗标只能被炸药等爆炸物烹饪，爆炸会使其烹饪等级前进两级（从生到烧透再到烧焦）。为放置它的童子军创造一个一次性复活点，并保存与恢复放置时的全部状态。烹饪：只能用爆炸物烹饪，烹饪时等级提升两级。' WHERE name_en = 'Checkpoint Flag';
UPDATE item SET description_zh = '梨鲍菇是 PEAK 中的一种蘑菇，可在海岸、雨林、森蕈和方山找到，可作为食物食用。梨鲍菇没有有毒变种。' WHERE name_en = 'Chubby Shroom';
UPDATE item SET description_zh = '云雾菇是 PEAK 中的可放置物品，可在森蕈的红杉树侧找到。它能像踏板菇一样在半空中造出可行走的平台。掷向墙面时会生成平台。在抛物线的最高点处也会生成平台。' WHERE name_en = 'Cloud Fungus';
UPDATE item SET description_zh = '银针菇是 PEAK 中的一种蘑菇，可在海岸、雨林、森蕈和方山找到，可作为食物食用。有毒变种长有带裙边的菌柄，会在食用 10 秒后开始、在 16 秒内缓慢造成 40 点中毒。' WHERE name_en = 'Cluster Shroom';
UPDATE item SET description_zh = '银针菇（有毒）是 PEAK 中的一种蘑菇，可在海岸、雨林、森蕈和方山找到，可作为食物食用。有毒变种长有带裙边的菌柄，会在食用 10 秒后开始、在 16 秒内缓慢造成 40 点中毒。' WHERE name_en = 'Cluster Shroom (Poisonous)';
UPDATE item SET description_zh = '椰子 是 PEAK 中的物品，长在海岸、雨林的树上，方山的绿洲树上也有。可以爬上棕榈树摘取，也可以朝椰子投掷其它物品把它打落。椰子砸开后可以得到两个半边椰子。朝玩家投掷椰子能将其撞倒，使其进入布娃娃状态。烹饪过的椰子会产出烹饪过的半边椰子。' WHERE name_en = 'Coconut';
UPDATE item SET description_zh = '罗盘是 PEAK 中的装备类物品，始终指向顶峰生态。' WHERE name_en = 'Compass';
UPDATE item SET description_zh = '海螺是 PEAK 中的物品。海岸的沙滩上散落着若干海螺壳。烹饪海螺除外观外没有任何效果。海螺没有实际用途。' WHERE name_en = 'Conch';
UPDATE item SET description_zh = '“鸟”烧熟了是 PEAK 中的天然食物，敲开火山鸟巢里的好大蛋有 10% 的概率获得，敲开雾沼鸟巢里的小小蛋有 1% 的概率获得。它出现时就已经是烹饪状态，再次烹饪会使其变成烧透。在关闭吃人选项时食用“鸟”烧熟了，会为玩家解锁成就「丰饶」。来源：敲开好大蛋时有 10% 的概率取代煎蛋出现。' WHERE name_en = 'Cooked Bird';
UPDATE item SET description_zh = '万灵药是 PEAK 中的消耗性神秘物品，可在古老行李箱中找到，或从古老雕像处获得。它共可使用 3 次，饮用后会从体力条上移除多种状态效果：热量、寒冷、伤害、中毒、孢子、困倦各 35 点，荆棘 25 点，诅咒 5 点，并恢复 20 点饱食。饮用万灵药还会移除玩家身上的中毒持续效果，但不会移除困倦持续效果。丢弃或烹饪万灵药会使其破碎，按距离远近对 4.8 米内的玩家最多移除 5、10 与 20 点不等的负面状态；这种方式无法阻止尚未结束的中毒持续效果继续施加中毒。把万灵药直接砸向玩家则会将其撞倒，使其进入布娃娃状态。最多移除 35 点热量、35 点寒冷、35 点伤害、35 点中毒、35 点孢子、35 点困倦、25 点荆棘与 5 点诅咒。烹饪：爆炸，按距离远近对 4.8 米内的所有玩家最多移除 5、10 与 20 点不等的负面状态。' WHERE name_en = 'Cure-All';
UPDATE item SET description_zh = '诅咒头骨是 PEAK 中的消耗性神秘物品。与其它神秘物品不同，它只会出现在古老行李箱中，无法从古老雕像获得。使用后，激活它的玩家会立即死亡，1440 米内的其它所有玩家则获得 100 点加成，并被清除除石化以外的一切负面状态。尝试烹饪诅咒头骨会立刻将其激活并引发一次炸药爆炸，物品随之销毁。若诅咒头骨是通过投入岩浆、留在灼热地面上或使用爆炸物而被烹饪，它同样会激活，但不会杀死任何童子军。若岩浆或灼热地面烹饪了背在身上的背包里的诅咒头骨，玩家不会死亡，但会受到爆炸造成的伤害与击退。若玩家已放置检查点旗标再使用诅咒头骨，则会获得 50 点加成，其余仍按检查点旗标的常规复活规则处理。单人游戏时不会出现诅咒头骨。使用后立即杀死持有它的童子军，并使其它玩家获得 50 点加成、清除除石化外的所有负面状态。只能从古老行李箱中获得。单人游戏时不会出现。烹饪：立即激活，随后引发一次炸药爆炸。' WHERE name_en = 'Cursed Skull';
UPDATE item SET description_zh = '炸药是 PEAK 中的消耗品，可在行李箱中、方山的地面上找到，偶尔也会出现在其它生态的小丑行李箱箱里。若童子军位于炸药 8 米以内（或炸药本身就在行李箱内被发现），引信会自动点燃，5 秒后爆炸。爆炸可对 9.6 米内的玩家造成最多 27.5 点伤害，若炸药被拿在手上则额外造成 25 点伤害。在无处可躲或附近有太多不知所措的童子军时，可以把炸药捡起并扔出去。尝试烹饪炸药会使其立即引爆。炸药的爆炸会烹饪附近的其它物品，若那些物品恰好也是炸药，就会引发连锁反应。炸药还可作为喷气背包的燃料，时机拿捏得当便既好用又安全。炸药上印的 “FIVE BIG BOOMS” 字样可能是在玩某个梗。烹饪：立即爆炸。' WHERE name_en = 'Dynamite';
UPDATE item SET description_zh = '煎蛋是 PEAK 中的天然食物，敲开火山中秃鹫巢里的好大蛋，或敲开雾沼中渡鸦巢里的小小蛋即可获得。它是解锁成就「美食家」所需的食物之一。来源：敲开好大蛋后获得。' WHERE name_en = 'Egg';
UPDATE item SET description_zh = '能量饮料是 PEAK 中的包装食品，可在普通或大号行李箱中找到。饮用后会立即移除 30 点热量与 50 点困倦，玩家同时获得 11 秒的奔跑速度 +50% 与攀爬速度 +150% 加成，开始攀爬后最长持续时间缩短为 8 秒。效果生效期间，玩家不会累积困倦。效果结束后，玩家立即获得 25 点困倦。烹饪能量饮料后饮用会使其爆炸，虽不造成伤害，但会把 9.6 米内的玩家（包括使用者）炸开；此外效果持续时间延长至 15 秒，开始攀爬后缩短为 12 秒，且之后不再获得困倦，此前被移除的困倦也仍会返还。效果：临时提升移动速度。' WHERE name_en = 'Energy Drink';
UPDATE item SET description_zh = '仙子提灯是 PEAK 中的神秘装备类物品。点燃后，提灯周围 7.2 米内的所有玩家每秒被移除 2.5 点或 5 点不等的热量、寒冷、伤害、中毒、孢子与困倦，并且免疫迷雾。仙子提灯最多可点燃 30 秒，燃料耗尽后熄灭。提灯被丢弃或放进被丢下的背包时仍会保持点燃；被收起、装有它的背包被捡起，或它从背包中被取出时会自动熄灭。仙子提灯可用于焚烧雾沼中的大幽灵，为玩家解锁成就「驱魔人」。在仍有余料时烹饪仙子提灯会使其爆炸，按距离远近为 4.8 米内的童子军最多移除 25 点热量、寒冷、伤害、中毒、孢子与困倦。可在 30 秒内持续为附近玩家移除 75 点热量、150 点寒冷、75 点伤害、75 点中毒、150 点困倦与 75 点孢子。可以熄灭提灯以保留剩余燃料。收在被丢下的背包里时会保持点燃。烹饪：爆炸，对 4.8 米内的所有玩家最多各移除 25 点。' WHERE name_en = 'Faerie Lantern';
UPDATE item SET description_zh = '滑稽背包是 PEAK 中的装备类物品。它与背包类似，占用第四个装备栏，可让童子军在攀爬途中多携带两件物品。单人探险中不会出现滑稽背包。' WHERE name_en = 'Fanny Pack';
UPDATE item SET description_zh = '急救箱是 PEAK 中的消耗品，可在行李箱中找到。使用急救箱会移除童子军身上的伤害、中毒（包括尚未结束的中毒持续效果）与孢子。烹饪急救箱没有任何效果，即使烧焦也一样。使用需要 5 秒。烹饪：无效果。' WHERE name_en = 'First Aid Kit';
UPDATE item SET description_zh = '照明棒是 PEAK 中的消耗品，可在坠机点与行李箱中找到，顶峰生态一只装满照明棒的小箱子里也有，但在进行天阶 4 及以上难度时不会出现。点燃照明棒会升起一道与使用者所属童子军颜色相同的高大彩色烟柱。在顶峰生态点燃照明棒可向救援直升机发出信号，完成本次探险。照明棒一旦点燃，便无法再收进物品栏或背包。烹饪照明棒会使其爆炸，按距离远近对 4.8 米内的童子军造成最多 20 点伤害。可点燃并升起一道与玩家所属童子军颜色相同的高大彩色烟柱。在顶峰生态使用可召唤救援直升机。烹饪：爆炸，对 4.8 米内的所有玩家造成最多 20 点伤害。' WHERE name_en = 'Flare';
UPDATE item SET description_zh = '飞盘是 PEAK 中的物品，只出现在海岸的坠机点。朝玩家掷出飞盘能将其撞倒，使其进入布娃娃状态。接住从 100 米以外掷来的飞盘会解锁成就「极限」。可朝其它童子军掷出以将其撞倒。可用于解锁成就「极限」。' WHERE name_en = 'Flying Disc';
UPDATE item SET description_zh = '奶白金是 PEAK 中的物品。饮用后会移除 50 点热量并恢复 10 点饱食，同时获得 15 秒的无敌效果。在此期间，童子军无法再获得任何其它状态效果，既有的状态效果也不会被移除。童子军仍可能被某些方式杀死，例如被另一名童子军吃掉。首次烹饪奶白金可将其无敌效果的持续时间延长 10 秒，过度烹饪则没有额外效果。若骷髅饮用奶白金，还会额外治疗 100 点伤害。烹饪：无敌时间延长 10 秒。' WHERE name_en = 'Fortified Milk';
UPDATE item SET description_zh = '青蛙是雾沼中的生物。它平时漫无目的地四处蹦跳，直到有童子军靠得太近，便会用长舌头把对方拽向自己。' WHERE name_en = 'Frog';
UPDATE item SET description_zh = '田鸡腿是 PEAK 中的天然食物。要得到烹饪过的田鸡腿，玩家必须捡起雾沼中的青蛙并将其烹饪。尽管未烹饪的田鸡腿存在于游戏文件中，正常游戏途径却无法获得。烹饪一次可让恢复的饱食翻倍，并获得 10 点加成。通过烹饪青蛙获得。' WHERE name_en = 'Frog Legs';
UPDATE item SET description_zh = '滑翔伞是 PEAK 中的物品。拿在手上时，使用者可以在空中滑翔。滑翔每秒消耗 20 点体力，体力不足时便无法使用滑翔伞。不着地滑翔 100 米会解锁成就「御风翱翔」。烹饪滑翔伞除外观外没有任何效果，即使烧糊或烧焦也一样。' WHERE name_en = 'Glider';
UPDATE item SET description_zh = '金刺莓是 PEAK 中的天然食物，长在方山的仙人掌上。食用后可恢复 15 点饱食与 10 点热量，治疗 10 点伤害，并在童子军头上附着 2 根尖刺，造成 10 点荆棘。由于尖刺附着在头上，玩家无法自行取下。烹饪金刺莓除了有烹饪的常规效果外，还会移除荆棘效果。烹饪：移除荆棘效果。' WHERE name_en = 'Gold Prickleberry';
UPDATE item SET description_zh = '燕麦棒是 PEAK 中的包装食品，可在普通或大号行李箱中找到。' WHERE name_en = 'Granola Bar';
UPDATE item SET description_zh = '绿脆莓是 PEAK 中的天然食物，长在海岸与雨林的灌木上，有时也会出现在森蕈与雪山顶部营火周围、雪山温泉与方山绿洲附近，以及顶峰山脚下的灌木上。食用后可恢复 5 点饱食，并在食用 2 秒后开始、在 4 秒内造成 10 点中毒。烹饪绿脆莓会移除中毒效果。烹饪：移除中毒效果。' WHERE name_en = 'Green Crispberry';
UPDATE item SET description_zh = '青荔莓是 PEAK 中的天然食物，长在雨林的树上。食用后可恢复 30 点饱食，并立即造成 5 点中毒。尽管会中毒，生吃青荔莓几乎总是划算的，因为它恢复的饱食远多于它造成的中毒。烹饪青荔莓会移除中毒效果。烹饪：移除中毒效果。' WHERE name_en = 'Green Kingberry';
UPDATE item SET description_zh = '绿菇莓是菇莓的一种。食用后会产生一个随机的负面效果。烹饪绿菇莓会移除孢子效果。食用后产生一个负面效果。烹饪：移除 5 点孢子效果。' WHERE name_en = 'Green Shroomberry';
UPDATE item SET description_zh = '旅行指南是 PEAK 中的装备类物品，只出现在海岸的坠机点。它是一本可阅读的游戏教程，讲解体力条、烹饪食物等各种玩法机制，由童军领队迈尔斯撰写。被烹饪后，旅行指南会被烧焦，再也无法打开或合上；若在烹饪前就已经打开，玩家仍可继续翻页。丢弃或收起旅行指南会使其合上，并且无法再次打开。一本讲解基础玩法的生存指南。烹饪：立即烧焦。' WHERE name_en = 'Guidebook';
UPDATE item SET description_zh = '半边椰子 是 PEAK 中的天然食物，敲开长在海岸、雨林树上或绿洲树上的完整椰子即可获得。食用后可恢复 10 点饱食并移除 30 点热量。烹饪一次可让恢复的饱食翻倍，并额外获得 10 点加成。它是解锁成就「美食家」所需的食物之一。来源：砸开一个大椰子可得 2 个半边椰子。' WHERE name_en = 'Half-Coconut';
UPDATE item SET description_zh = '暖宝宝是 PEAK 中的消耗品。使用暖宝宝后，接下来 60 秒内每秒移除 6 点寒冷。暖宝宝只会在雪山的行李箱中出现。烹饪暖宝宝会使其爆炸，按距离远近对 4.8 米内的玩家造成最多 20 点伤害。烹饪：爆炸，对 4.8 米内的所有玩家造成最多 20 点伤害。' WHERE name_en = 'Heat Pack';
UPDATE item SET description_zh = '蜂巢蜜是 PEAK 中的天然食物，有几率在森蕈的红杉树桩里找到，或在雨林打破蜂巢获得（每个蜂巢产出四个蜂巢蜜）。食用后可恢复 10 点饱食并获得 50 点加成。它是解锁成就「美食家」所需的食物之一。来源：打破蜂巢可得 4 个蜂巢蜜。' WHERE name_en = 'Honeycomb';
UPDATE item SET description_zh = '热狗肠是 PEAK 中的天然食物，可在营火附近找到。每处营火会为探险中的每名玩家生成一根棉花糖（62.5%）或一根热狗肠（37.5%）。热狗肠也会伪装成香蒲藏在雾沼中。在 5 秒内吃掉（或被喂食）3 根热狗肠可解锁成就「大胃王奖章」。来源：营火，以及雾沼中的香蒲丛；有 37.5% 的概率替代棉花糖出现。' WHERE name_en = 'Hot Dog';
UPDATE item SET description_zh = '喷气背包是 PEAK 中的可穿戴装备。它与背包一样占用第四个装备栏位，两者无法同时穿戴。每个喷气背包的燃料初始都是满的。处于空中时，按下或按住空格键即可启动喷气背包，让童子军缓慢升空，每秒消耗 20% 的燃料。烹饪喷气背包没有效果。' WHERE name_en = 'Jetpack';
UPDATE item SET description_zh = '国王是 PEAK 中的物品，可在机场找到。棋子被放下时会自动固定在地面上，以免被意外碰移。机场中一共有两枚国王棋子，黑白各一枚，都摆在棋盘上。' WHERE name_en = 'King';
UPDATE item SET description_zh = '骑士是 PEAK 中的物品，可在机场找到。棋子被放下时会自动固定在地面上，以免被意外碰移。机场中一共有四枚骑士棋子，黑白各两枚，都摆在棋盘上。' WHERE name_en = 'Knight';
UPDATE item SET description_zh = '提灯是 PEAK 中的装备。坠机点可以找到一盏，雨林与雪山的行李箱中也可能找到更多。点亮时，提灯 7.2 米内的所有童子军每秒降低 2.5 点寒冷。提灯最多可点亮 60 秒，之后燃料耗尽。提灯被放下或放进已放下的背包时仍会保持点亮；被收起、装有它的背包被拾起，或它被从背包中取出时，则会自动熄灭。在仍有燃料时烹饪提灯会使其爆炸，对 4.8 米内的童子军造成最高 20 点伤害，具体数值取决于距离。可以熄灭提灯以保留剩余燃料。放在已放下的背包中时仍会保持点亮。烹饪：爆炸，对 4.8 米内的所有玩家造成最高 20 点伤害。' WHERE name_en = 'Lantern';
UPDATE item SET description_zh = '魔豆是 PEAK 中的可放置物，生长在海岸、雨林、森蕈、雪山与方山的环境中。放下或投掷后等待 3 秒，魔豆便会开始长出豆茎，若前方无遮挡，最高可达 12 米。攀爬豆茎的玩家移动速度为平时的两倍，且不额外消耗体力。魔豆在开始生长前仍可被拾起。' WHERE name_en = 'Magic Bean';
UPDATE item SET description_zh = '曼德拉草是 PEAK 中的天然食物。在森蕈，它有 28.57% 的概率替代药用根茎生成。在被拔起之前，它看起来与药用根茎完全相同。一旦被拔起且附近有清醒的玩家，曼德拉草会持续尖叫 3 秒，随后冷却 0.75–2 秒。尖叫期间，16 米内的玩家每 0.25 秒受到 5 点伤害。烹饪曼德拉草可以停止尖叫。曼德拉草无法放入玩家的物品栏，但可以放进背包。食用（或被喂食）熟曼德拉草可解锁成就「秘传料理奖章」，并移除 25 点负面状态。生吃（或被喂食）曼德拉草会让玩家陷入 60 秒的麻木状态，并隐藏体力条 60 秒。烹饪：停止尖叫并移除 25 点负面状态。' WHERE name_en = 'Mandrake';
UPDATE item SET description_zh = '棉花糖是 PEAK 中的天然食物，可在营火附近找到。每处营火会为探险中的每名玩家生成一根棉花糖（62.5%）或一根热狗肠（37.5%）。' WHERE name_en = 'Marshmallow';
UPDATE item SET description_zh = '药用根茎是 PEAK 中的天然食物，生长在海岸、雨林、森蕈与方山的地面上。烹饪药用根茎后，除常规效果外，还会额外移除 20 点中毒和 20 点孢子。烹饪：额外移除 20 点中毒和 20 点孢子。' WHERE name_en = 'Medicinal Root';
UPDATE item SET description_zh = '晚安莓是 PEAK 中的天然食物，生长在雪山的山洞中。食用它会移除除困倦以外的所有状态效果，但会同时替换整条体力条，使玩家昏迷一段时间，直到效果逐渐消退。玩家靠近未采摘的晚安莓植株、且植株处于镜头视野内时，也会累积困倦。' WHERE name_en = 'Napberry';
UPDATE item SET description_zh = '橙雪莓是 PEAK 中的天然食物，生长在雪山的树上。' WHERE name_en = 'Orange Winterberry';
UPDATE item SET description_zh = '潘多拉餐盒是 PEAK 中的消耗型神秘物品。使用后，它会清除玩家身上的全部状态效果（少数除外），随后随机给予玩家若干点饱食度、加成、热量、寒冷、伤害、中毒、孢子与困倦等状态。它不会移除持续时间型状态，例如食用有毒食物或被僵尸咬伤后获得的状态；不过若玩家在使用潘多拉餐盒后饱食度归零，僵尸感染仍会停止。潘多拉餐盒给予的状态值总量在 0–100 之间，平均约 40 点，其中一项状态的平均值只有其它状态的一半。玩家可获得的状态值在 0–100 之间（受上限限制），平均约 30 点。潘多拉餐盒的效果会无视无敌状态，作用即随机化使用者的状态效果。烹饪潘多拉餐盒会使其爆炸，并将效果作用于 4.8 米内的所有玩家。烹饪：爆炸，效果作用于 4.8 米内的所有玩家。' WHERE name_en = 'Pandora''s Lunchbox';
UPDATE item SET description_zh = '太阳伞是 PEAK 中的装备，可在森蕈与方山的行李箱中找到，也能在任何生态的小丑行李箱中找到。它可以在下落时减缓玩家的下降速度，让玩家安全落地、不受伤害，同时还能提供一定的遮阳效果。不过，跳跃跨越沟壑时不应使用太阳伞，因为撑伞下落会大幅降低水平移动速度。在森蕈被强风吹动时，撑开太阳伞反而会让玩家以更快的速度被拖向远处。它在方山可以保护玩家免受强烈阳光的伤害，并在空中减缓玩家的下落速度。' WHERE name_en = 'Parasol';
UPDATE item SET description_zh = '护照是 PEAK 中的大厅专属物品，可以让玩家自定义童子军的外观。可自定义的项目包括肤色、发型、眼睛、嘴部、服装（衣服/装扮）、帽子与绶带。护照只能在机场使用，且无法被丢弃。' WHERE name_en = 'Passport';
UPDATE item SET description_zh = '兵卒是 PEAK 中的物品，可在机场找到。棋子被放下时会自动固定在地面上，以免被意外碰移。机场中一共有 16 枚兵卒棋子，黑白各八枚，都摆在棋盘上。' WHERE name_en = 'Pawn';
UPDATE item SET description_zh = '粉莓蕉是 PEAK 中的天然食物，生长在雨林的藤蔓上。食用粉莓蕉会恢复 15 点饱食度，并在食用 2 秒后开始，于 6 秒内缓慢累积 15 点中毒。食用莓蕉后，玩家会获得一个粉莓蕉皮；若把粉莓蕉喂给其他玩家，蕉皮归对方所有，对方的物品栏与双手都已满时，蕉皮会掉落在他脚下。烹饪粉莓蕉可以移除中毒效果。烹饪：移除中毒效果。' WHERE name_en = 'Pink Berrynana';
UPDATE item SET description_zh = '粉莓蕉皮是 PEAK 中的物品，食用雨林的粉莓蕉后获得。玩家踩到蕉皮会滑倒摔在地上，短暂失去控制。来源：食用粉莓蕉后获得。' WHERE name_en = 'Pink Berrynana Peel';
UPDATE item SET description_zh = '海盗罗盘是 PEAK 中的装备。罗盘会指向最近的未开启行李箱或未使用的古老雕像。' WHERE name_en = 'Pirate''s Compass';
UPDATE item SET description_zh = '岩钉（读作 pē-tän）是 PEAK 中的可放置物。只要它在物品栏中，童子军就能在攀爬时不下落，直接把它钉在崖壁上。钉入后它会成为永久的手持点，让童子军抓住它恢复体力。同一枚岩钉一次只能供一名童子军攀附。抓住岩钉的方式是看向它并按下互动键。挂在岩钉上时无需按住攀爬键。把岩钉插入崖壁的过程中会显示落点预览，只有预览为蓝色时才能钉入。插入期间童子军的体力消耗会大幅降低，但任何移动都会重置插入进度。它可附着在任何可攀爬表面，为童子军提供抓握与恢复体力的支点，一次仅限一人。挂在已钉好的岩钉上时，仍可使用主物品栏中的物品。烹饪：立即焚毁。' WHERE name_en = 'Piton';
UPDATE item SET description_zh = '便携火炉是 PEAK 中的可放置物，可在海岸以外任意生态的行李箱中找到。把它放下后即可烹饪物品，并每秒为 3.2 米内的玩家移除 5 点寒冷。便携火炉会在 1 分钟后自行熄灭。烹饪便携火炉会使其爆炸，对 4.8 米内的童子军造成最高 20 点伤害，具体数值取决于距离。烹饪：爆炸，对 4.8 米内的所有玩家造成最高 20 点伤害。' WHERE name_en = 'Portable Stove';
UPDATE item SET description_zh = '紫荔莓是 PEAK 中的天然食物，生长在雨林的树上。食用它会恢复 30 点饱食度并获得 35 点加成。与其他种类的荔莓不同，食用紫荔莓没有任何负面效果。' WHERE name_en = 'Purple Kingberry';
UPDATE item SET description_zh = '紫菇莓是菇莓的一种。食用时会产生随机的好或坏效果。烹饪紫菇莓可以移除孢子效果。烹饪：移除 5 点孢子效果。' WHERE name_en = 'Purple Shroomberry';
UPDATE item SET description_zh = '皇后是 PEAK 中的物品，可在机场找到。棋子被放下时会自动固定在地面上，以免被意外碰移。机场中一共有四枚皇后棋子：黑白各一枚摆在棋盘上，另一枚同色皇后棋子则放在旁边。' WHERE name_en = 'Queen';
UPDATE item SET description_zh = '红葚莓是 PEAK 中的天然食物，生长在雨林的巨型常春藤上。' WHERE name_en = 'Red Clusterberry';
UPDATE item SET description_zh = '红脆莓是 PEAK 中的天然食物，常见于海岸与雨林的灌木丛。森蕈营火周围、雪山温泉与营火附近、方山绿洲以及顶峰山脚下的灌木丛上偶尔也会生长。烹饪一次可让恢复的饱食度翻倍，并获得 10 点加成。' WHERE name_en = 'Red Crispberry';
UPDATE item SET description_zh = '红刺莓是 PEAK 中的天然食物，生长在方山的大型仙人球上。食用它可恢复 15 点饱食度、降低 10 点热量，并在童子军头上附着 2 根尖刺，累积 10 点荆棘。由于尖刺附着在头部，玩家无法自行将其取下。烹饪红刺莓时，除常规烹饪效果外，还会移除荆棘效果。烹饪：移除荆棘效果。' WHERE name_en = 'Red Prickleberry';
UPDATE item SET description_zh = '红菇莓是菇莓的一种。食用时会产生随机的好效果。烹饪红菇莓可以移除孢子效果。烹饪：移除 5 点孢子效果。' WHERE name_en = 'Red Shroomberry';
UPDATE item SET description_zh = '灵药菇是 PEAK 中的消耗品。被放下或投掷时，它会释放一次爆炸，立即为 8 米内的玩家治疗 17.5 点伤害；若玩家留在效果范围内，还会在 14 秒内额外移除 35 点伤害、35 点中毒与 35 点孢子。放下时会生成一团范围 8 米的治疗烟雾。' WHERE name_en = 'Remedy Fungus';
UPDATE item SET description_zh = '救援抓钩是 PEAK 中的消耗品，可在全岛的普通与大号行李箱箱中找到。它既能将持有者拉向地形，也能把其他童子军拉向自己。向上瞄准时，抓钩的射程为 48 米；向下瞄准时，射程为 64 米。用救援抓钩将一名昏迷的童子军拖行 30 米可解锁成就「灾难响应奖章」。烹饪救援抓钩会立即将其焚毁，无法再使用。烹饪：立即焚毁。' WHERE name_en = 'Rescue Claw';
UPDATE item SET description_zh = '仪式匕首是 PEAK 中的消耗型神秘物品，在合作模式下可从古老行李箱或古老雕像处获得。从背后「献祭」另一名童子军即可使用这把匕首：目标童子军会死亡，而使用者及其周围小范围内的玩家会治疗大部分负面状态。仪式匕首可以被烹饪，但功能与效果都不会改变。单次使用移除超过 75% 的负面状态可解锁成就「末路手段奖章」。' WHERE name_en = 'Ritual Dagger';
UPDATE item SET description_zh = '火箭背包是 PEAK 中的可穿戴装备。它与背包一样占用第四个装备栏位，两者无法同时穿戴。穿戴后，其他童子军或穿戴者本人（角度合适时）都可以点燃火箭背包的引信。3 秒后火箭点火并持续 3 秒，带着穿戴者飞上天空。飞行期间可以用方向键略微调整飞行方向，但操控性非常有限。飞行时间结束后，火箭会炸成烟花，对附近的童子军造成最高 20 点伤害。' WHERE name_en = 'Rocketpack';
UPDATE item SET description_zh = '战车是 PEAK 中的物品，可在机场找到。棋子被放下时会自动固定在地面上，以免被意外碰移。机场中一共有四枚战车棋子，黑白各两枚，都摆在棋盘上。' WHERE name_en = 'Rook';
UPDATE item SET description_zh = '绳索炮是 PEAK 中的可放置物。使用绳索炮可以把一根 7.5 米长的绳索固定到最远 48 米外的表面上，并通过钩爪将绳索一端嵌入表面。它是反重绳索炮的普通版本。烹饪绳索炮会立即将其焚毁，无法再使用。它会射出一枚鱼叉，接触到可附着的表面时便垂下一段绳索。烹饪：立即焚毁。' WHERE name_en = 'Rope Cannon';
UPDATE item SET description_zh = '绳索是 PEAK 中的一件可放置物。一捆绳索总长 12.5 米，可分段放置为 0.75 米至 10 米长。放置后，童子军攀爬绳索消耗的体力低于正常攀爬。反重绳索是绳索的反重力版本。烹饪绳索会立刻把它烧成灰烬，使其无法使用。可放置出可攀爬的绳段（最长 10 米），附着在任何可攀爬的表面上。绳索受重力影响。每捆含 12.5 米绳索。烹饪：立刻烧成灰烬。' WHERE name_en = 'Rope Spool';
UPDATE item SET description_zh = '火烧莓是 PEAK 中的一种天然食物，生长在雨林的灌木上，也会出现在森蕈或雪山的营火旁以及雪山的温泉附近。' WHERE name_en = 'Scorchberry';
UPDATE item SET description_zh = '蝎子是栖息在方山的生物，见于该地区的峡谷与峭壁。它四处游荡，一旦发现童子军就会试图蜇刺对方。手动烹饪蝎子，或用炸药把它炸熟，即可获得。不能生吃。可以用手拿着，但不能放入任何物品栏格子。' WHERE name_en = 'Scorpion';
UPDATE item SET description_zh = '童军大炮是 PEAK 中的一件可放置物，可在行李箱中找到。大炮能把玩家发射到极远的距离。架设时先调整角度和落点，再放下大炮；点燃引信后让一名玩家进入炮口即可发射。引信约在 3 秒后触发。玩家被发射出去开始下坠时，会获得持续 5 秒的减速效果以免摔伤，作用类似撑开的太阳伞。烹饪童军大炮会让它像炸药一样爆炸，但不附带手持时的额外伤害。使用后会放下一门大炮，引信点燃后进入炮口即被发射飞出。烹饪：像炸药一样爆炸，但不附带手持时的额外伤害。' WHERE name_en = 'Scout Cannon';
UPDATE item SET description_zh = '童军饼干是 PEAK 中的一种包装食品，可在普通行李箱箱或大号行李箱中找到。可使用 4 次，每次恢复 10 点饱食度并获得 10 点加成。' WHERE name_en = 'Scout Cookies';
UPDATE item SET description_zh = '童军雕像是 PEAK 中的一件消耗型神秘物品，可从古老行李箱中取得，也能从古老雕像处获得。雕像可在目标位置随机复活一名已死亡或昏迷的玩家。如果在没有鬼魂状态童子军时放置，雕像仍会被消耗，但不会复活任何人。烹饪童军雕像后，使用时额外提供 10 点增益。烧成灰烬后使用，会像其他烧焦的食物一样给使用者附加负面效果。单人游玩时不会生成童军雕像。可在目标位置复活一名已死亡的童子军。单人游玩时不会生成。' WHERE name_en = 'Scout Effigy';
UPDATE item SET description_zh = '童军的野心是 PEAK 中的一件神秘物品。作为护身符，它可以从山上各处分布的护身符雕像处获得。使用时，使用者周围会形成一个半径 9.6 米、持续 8 秒的黄色气泡，为使用者和气泡内的所有童子军提供无限体力。使用时使用者获得 30 点增益。童军的野心不能烹饪。' WHERE name_en = 'Scout''s Ambition';
UPDATE item SET description_zh = '童军的盛情是 PEAK 中的一件神秘物品。作为护身符，它可以从山上各处分布的护身符雕像处获得。使用时，它会复制一件离得足够近、已被高亮的物品。复制普通物品时使用者获得 25 点增益，复制神秘物品时获得 45 点增益。护身符、童军雕像和检查点旗标无法被童军的盛情复制。童军的盛情不能烹饪。' WHERE name_en = 'Scout''s Generosity';
UPDATE item SET description_zh = '童军的荣耀是 PEAK 中的一件神秘物品，把四枚护身符献给顶峰的石头童军后，奇怪水晶会转变为它。童子军可以按住鼠标左键与之共鸣，屏幕会剧烈扭曲，随后把所有玩家传送到 Nadir。烹饪童军的荣耀时，它会爆炸成一个直径 40 米的反重球体，把范围内的所有童子军从中心弹开，随后迅速消失。此外还会生成一名以烹饪者为目标的童军领队，追击其长达 1 小时。' WHERE name_en = 'Scout''s Honor';
UPDATE item SET description_zh = '童军的进取是 PEAK 中的一件神秘物品。作为护身符，它可以从山上各处分布的护身符雕像处获得。使用时，为使用者和其周围 12.8 米内的所有童子军施加缓降效果，随后为所有受影响的童子军施加 3 秒的御风行走。使用时使用者获得 7 点增益。童军的进取不能烹饪。' WHERE name_en = 'Scout''s Initiative';
UPDATE item SET description_zh = '童军的毅力是 PEAK 中的一件神秘物品。作为护身符，它可以从山上各处分布的护身符雕像处获得。它可以用在持有者自己或另一名童子军身上，按固定顺序治疗以下状态，总计最多 60 点：热量、寒冷、伤害、中毒、孢子、困倦。之后会根据治疗的伤害量给使用者附加 10 至最多 30 点的加成，以及 10 秒的无敌。童军的毅力不能烹饪。' WHERE name_en = 'Scout''s Tenacity';
UPDATE item SET description_zh = '童军领队的喇叭是 PEAK 中的一件神秘装备。它有极小的概率从古老行李箱或古老雕像处获得。吹响它会发出与普通喇叭截然不同的失真噪音。童军领队的喇叭只能使用一次。使用时会为使用者和所有其他童子军提供士气高扬，给予 100 点加成。它还会召唤童军领队，并把喇叭的使用者标记为他的目标。菜鸟新人难度下童军领队不会出现。童军领队会追击目标 2 分钟后消失，不受其常规消失条件的限制。如果把童军领队的喇叭烧成灰烬，吹奏时会像食用烧成灰烬的食物一样给使用者附加相同的负面效果。站在水豚旁边吹奏童军领队的喇叭可解锁成就「对牛弹琴奖章」，且喇叭无需被消耗即可解锁该奖章。使用者和附近的童子军获得 100 点加成。召唤童军领队 2 分钟，并把使用者标记为他的目标。比其他神秘物品稀有得多。' WHERE name_en = 'Scoutmaster''s Bugle';
UPDATE item SET description_zh = '卷轴是 PEAK 中的一件物品，可在除火山和雾沼之外各地区顶部的营火处找到。打开卷轴会显露一页撕下的书页，具体显露哪一页取决于打开它的玩家。卷轴被打开时，会显露该玩家满足条件且编号最高的未读书页；如果该玩家已读过当前所有可获得的书页，则随机生成一页可获得的书页。地区条件以最近的营火为准，无论它是否被点燃。显露或阅读第 12 页可解锁成就「书呆子奖章」。每一页撕下的书页都是童军领队迈尔斯的日记，记录他在这座岛上的经历。烹饪卷轴后，使用时额外提供 10 点增益。可以打开以显露一页撕下的书页。' WHERE name_en = 'Scroll';
UPDATE item SET description_zh = '踏板菇是 PEAK 中的一件可放置物，常见于大多数地区的陡峭表面上。把它投出或丢出，在与地形、物品、玩家或其他有有效碰撞的物体撞击处会生成一块平台。被投出的物品和下坠的玩家也能触发踏板菇变成平台。投向墙壁时会生成一块平台。' WHERE name_en = 'Shelf Fungus';
UPDATE item SET description_zh = '小小蛋可在雾沼的渡鸦巢中找到，敲开后可获得一枚与好大蛋类似的煎蛋。敲开时有 99% 的概率生成煎蛋，1% 的概率生成「鸟」烧熟了。烹饪小小蛋会使敲开后得到的煎蛋同样处于已烹饪状态。' WHERE name_en = 'Small Egg';
UPDATE item SET description_zh = '雪球是 PEAK 中的一件物品，捡起地上的雪堆即可获得。雪球可以投掷，如果以足够快的速度撞上玩家或环境则会破碎。把雪球投向玩家会让其获得 5 至 10 点寒冷，并使其进入布娃娃状态。烹饪雪球会对玩家造成寒冷，但不会将其击倒。在雪地上滚动雪球会让它变大，但不影响其重量。雪球越大，投向玩家时造成的击退越强。当雪球大到一定程度后，就无法再被捡起。' WHERE name_en = 'Snowball';
UPDATE item SET description_zh = '运动饮料是 PEAK 中的一种包装食品，可在普通行李箱箱或大号行李箱中找到。饮用运动饮料可恢复 30 点加成，并移除使用者身上的 200 点热量。烹饪运动饮料会让童子军额外获得 15 点体力，总计 45 点。在第一次烹饪之后再继续烹饪运动饮料（包括烧成灰烬）没有额外效果。' WHERE name_en = 'Sports Drink';
UPDATE item SET description_zh = '奇怪水晶是 PEAK 中的一件神秘物品，出现在顶峰地区山顶后方石头童军的手中。捡起水晶并按下鼠标左键，屏幕左上角会显示「水晶已激活」；再次操作会显示「水晶已停用」。烹饪奇怪水晶会使它在被献出时额外提供 10 点增益；烧成灰烬后在同样情况下也会提供该效果。' WHERE name_en = 'Strange Gem';
UPDATE item SET description_zh = '防晒喷雾是 PEAK 中的一件消耗品，可在方山的行李箱中找到。使用后可生成一团跨度 4.8 米的云雾，为穿过它的任何玩家附加防晒效果，在方山提供 90 秒的日照伤害防护。防晒效果表现为童子军皮肤上的白色光泽，以及屏幕边缘的白色云雾质感。防晒云雾会在 4 秒后消散。烹饪防晒喷雾会让它爆炸，生成一团跨度 9.6 米的云雾，为其中所有童子军提供通常的 90 秒防晒效果，这团云雾同样会在 4 秒后消散。喷出一团防晒云雾，为进入其中的任何玩家提供 90 秒的防护，抵御方山强烈的阳光。烹饪：爆炸，为 4.8 米内的所有玩家附加防晒效果。' WHERE name_en = 'Sunscreen';
UPDATE item SET description_zh = '骸骨之书是 PEAK 中的一件消耗型神秘物品，可以把已死亡的童子军（以及活着的）变成活体骷髅。骸骨之书只能从古老雕像和古老行李箱中获得。烹饪骸骨之书没有效果，即便烧成灰烬也一样。对另一名已死亡的玩家使用骸骨之书可解锁成就「玄学致用奖章」。它会移除除诅咒之外的所有状态效果，并阻止继续获得任何状态效果（详见完整页面）。烹饪：无效果。' WHERE name_en = 'The Book of Bones';
UPDATE item SET description_zh = '早起虫儿是 PEAK 中的一个 NPC 兼天然食物，可在雾沼的地面上找到，绕圈移动。它可以被食用，会恢复 5 点饱食度并清除玩家身上的困倦。食用早起虫儿可解锁成就「神清气爽奖章」。当玩家靠近或手持一只活的早起虫儿时，能听到它独特的移动音效。烹饪后它会停止移动，但不会获得额外增益。来源：可在雾沼地表找到。烹饪：不会获得额外增益，虫子停止移动。' WHERE name_en = 'The Early Worm';
UPDATE item SET description_zh = '蜱虫是 PEAK 中的一种天然食物。童子军走过雨林的龟背竹时，蜱虫有 1% 的概率附着到其身上，并持续造成最多 50 点伤害，直到被取下。取下后可以食用，恢复 20 点饱食度。附着在童子军身上期间，蜱虫会随时间长大，但其大小不影响它恢复的饱食度量。与其他虫类生物一样，在设置中开启「虫子恐惧模式」后，蜱虫会变成它的宾邦版本。作为食物食用不会造成中毒。' WHERE name_en = 'Tick';
UPDATE item SET description_zh = '火炬是 PEAK 中的一件装备，仅出现在古墓内部，用作照明。手持未点燃的火炬时可以点燃它，提供额外的光源。仅在古墓内出现。可提供临时光源。' WHERE name_en = 'Torch';
UPDATE item SET description_zh = '混合坚果是 PEAK 中的一种包装食品，可在普通行李箱箱或大号行李箱中找到。' WHERE name_en = 'Trail Mix';
UPDATE item SET description_zh = '曲迁罗盘是 PEAK 中的一件神秘装备。自 1.1.a 版本起，由于行为异常，曲迁罗盘已无法在正常游戏中获得。使用时，它的预期效果是把玩家传送到另一名随机玩家处。在单人模式下没有效果。由于一个会在使用时把玩家传送到地图外的 bug，该物品在上线第二天就被移除。它不太可能在未来被重新加入。' WHERE name_en = 'Warp Compass';
UPDATE item SET description_zh = '曲迁菇是 PEAK 中的一件消耗品。丢弃或投掷时，会把使用者传送到它落地的位置。曲迁菇可在除雪山和方山之后的地区以外的所有地区找到。把使用者传送到它落地的位置。' WHERE name_en = 'Warp Fungus';
UPDATE item SET description_zh = '黄莓蕉是 PEAK 中的一种天然食物，生长在雨林和雾沼的藤蔓上。食用莓蕉后，玩家会获得一张黄莓蕉皮。如果把黄莓蕉喂给其他玩家，对方会获得这张皮；如果对方的物品栏和双手都已满，皮会掉在对方脚下。食用后产出一张黄莓蕉皮。' WHERE name_en = 'Yellow Berrynana';
UPDATE item SET description_zh = '黄莓蕉皮是 PEAK 中的一件物品，食用雨林或雾沼的黄莓蕉后获得。玩家走过蕉皮时会滑倒在地上，短暂失去控制。它也可以单独在小丑行李箱箱中获得。来源：食用黄莓蕉后获得。' WHERE name_en = 'Yellow Berrynana Peel';
UPDATE item SET description_zh = '黄葚莓是 PEAK 中的一种天然食物，生长在雨林的巨型常春藤上。' WHERE name_en = 'Yellow Clusterberry';
UPDATE item SET description_zh = '黄脆莓是 PEAK 中的一种天然食物，生长在海岸和雨林的灌木上。它们也可能长在森蕈和雪山营火旁的灌木上，以及雪山温泉与方山绿洲周围的灌木上，还有顶峰脚下。' WHERE name_en = 'Yellow Crispberry';
UPDATE item SET description_zh = '黄荔莓是 PEAK 中的一种天然食物，生长在雨林的树上。食用后恢复 30 点饱食度，并在食用 3 秒后开始，在 10 秒内缓慢造成 25 点中毒。烹饪黄荔莓会移除中毒效果。烹饪：移除中毒效果。' WHERE name_en = 'Yellow Kingberry';
UPDATE item SET description_zh = '黄菇莓是菇莓的一种。食用时会产生随机的好效果。烹饪黄菇莓会移除孢子效果。食用时产生好效果。烹饪：移除 5 点孢子效果。' WHERE name_en = 'Yellow Shroomberry';
UPDATE item SET description_zh = '黄雪莓是 PEAK 中的一种天然食物，生长在雪山的树上。它们也会出现在水豚的头上，这些水豚可以在雪山的温泉和方山的绿洲找到。黄雪莓长在树上的概率极低（0.5%）。获取它们最可靠的方式（例如为了美食家奖章）是找到雪山温泉或方山绿洲中的水豚，因为黄雪莓在这些位置有 100% 的生成概率。如果尚未食用过橙雪莓，黄雪莓可计入觅食奖章的进度。是美食家奖章的必需食材之一。' WHERE name_en = 'Yellow Winterberry';
